"""Render the material partition inventory as a self-contained review page."""
from pathlib import Path
import json
import argparse
ROOT=Path(__file__).resolve().parents[2]
parser=argparse.ArgumentParser()
parser.add_argument('--run',default='run_001')
args=parser.parse_args()
p=ROOT/'phase1/material_partition'/args.run
rows=json.loads((p/'inventory.json').read_text(encoding='utf-8'))
summary=json.loads((p/'summary.json').read_text(encoding='utf-8'))
data=json.dumps({'rows':rows,'summary':summary},ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MacroMind · 材料用途与封存候选</title><style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#193f43;background:#f4f7f6}body{margin:0;padding:32px;max-width:1500px;margin:auto}h1{font-size:28px;margin:0 0 12px}p{line-height:1.7}small{color:#52716f}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card,header,.filters{background:white;border:1px solid #d5e2df;border-radius:12px;padding:18px}.card b{display:block;font-size:30px;color:#087d70}.note{border-left:4px solid #e2ac3d;padding:12px 16px;background:#fff7e6;margin:18px 0;line-height:1.7}.filters{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin-bottom:18px}label{font-size:13px;display:flex;flex-direction:column;gap:6px}input,select,button{font:inherit;padding:9px;border:1px solid #adc5c0;border-radius:6px;background:white;color:#193f43}input{min-width:300px}button{cursor:pointer}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #e0e9e7;padding:13px;line-height:1.55}th{background:#e7f0ee;position:sticky;top:0;font-size:13px}td:first-child{width:43%}.tag{display:inline-block;padding:2px 7px;border-radius:4px;background:#e2f3ed;white-space:nowrap}.pending{background:#fff0cf}.regression{background:#e6e9ff}.development{background:#eee}.mono{font-size:12px;word-break:break-all;color:#577774}details{margin-top:8px;font-size:12px}summary{cursor:pointer;color:#087d70}.footer{display:flex;justify-content:space-between;margin:18px 0}@media(max-width:750px){body{padding:14px}.cards{grid-template-columns:repeat(2,1fr)}.tablewrap{overflow:auto}table{min-width:950px}input{min-width:180px}}
</style><header><small>MacroMind / 材料管理 / 版本 001</small><h1>材料用途与封存候选</h1><p>按BV号去重，保留使用证据，按标题与时间建立事件候选组。本次未读取原始字幕正文。<br>封存候选表示“未找到曝光记录并暂予保护”，不等于已认证的干净测试集。</p></header><div class="cards" id="cards"></div><div class="note">会员标记待确认：清单中实际使用<strong>《第中文数字期》</strong>，没有【】标题，暂记“会员候选”。会员身份是分层属性，不是质量保证。普通期数与中文期数不合并。<br>事件组由标题主题和时间邻近关系生成，可能过宽或遗漏关系；正式测试前需核对整组边界。第1078期有后续诊断证据，旧保留身份已失效。</div>
<div class="filters"><label>标题 / BV / 期号 / 事件组<input id="search" placeholder="搜索，例如：米荒、G0002、BV…"></label><label>用途<select id="partition"><option value="">全部用途</option><option value="development">开发</option><option value="regression">回归</option><option value="sealed_candidate">封存候选</option><option value="pending">待整理</option></select></label><label>会员标记<select id="member"><option value="">全部标记</option><option value="member_confirmed">会员视频（已确认）</option><option value="member_candidate">会员候选</option><option value="unmarked">未标记</option><option value="member_by_user_marker">符合用户【】标记</option></select></label><label>曝光<select id="exposure"><option value="">全部状态</option><option value="content_or_processing_exposed">内容或处理已暴露</option><option value="keyword_scanned">仅有关键词扫描记录</option><option value="no_exposure_record_found">未找到曝光记录</option></select></label><label>日期<select id="dated"><option value="">全部日期</option><option value="yes">日期已知</option><option value="no">日期未知</option></select></label><button id="clear">清空筛选</button></div><p id="status"></p><div class="tablewrap"><table><thead><tr><th>视频与依据</th><th>用途</th><th>日期 / 会员标记</th><th>事件组 / 曝光</th></tr></thead><tbody id="body"></tbody></table></div><div class="footer"><button id="more">再显示100条</button><small>只读审阅页 · 不会自动打开字幕或更改分组</small></div><script id="data" type="application/json">DATA_PLACEHOLDER</script><script>
const D=JSON.parse(document.getElementById('data').textContent), labels={development:'开发',regression:'回归',sealed_candidate:'封存候选',pending:'待整理'}, members={member_confirmed:'会员视频（已确认）',member_candidate:'会员候选',unmarked:'未标记',member_by_user_marker:'符合【】标记'},exp={content_or_processing_exposed:'内容或处理已暴露',keyword_scanned:'关键词扫描已暴露',no_exposure_record_found:'未找到曝光记录'};let limit=100;
const el=id=>document.getElementById(id);function node(tag,text,cls){let e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}Object.entries(labels).forEach(([key,name])=>{let c=node('div','', 'card');c.append(node('b',D.summary.partitions[key]||0),node('span',name));el('cards').append(c)});
function render(){let q=el('search').value.trim().toLowerCase();let found=D.rows.filter(r=>(!q||[r.title,r.bvid,r.public_episode,r.group_id,...r.event_families].join(' ').toLowerCase().includes(q))&&(!el('partition').value||r.partition===el('partition').value)&&(!el('member').value||r.membership===el('member').value)&&(!el('exposure').value||r.exposure===el('exposure').value)&&(!el('dated').value||Boolean(r.date)===(el('dated').value==='yes')));el('status').textContent=`共${D.rows.length}个视频 · 当前匹配${found.length}个 · 显示${Math.min(limit,found.length)}个 · 本地有字幕${D.summary.with_subtitles}个`;el('body').replaceChildren();for(let r of found.slice(0,limit)){let tr=node('tr',''),a=node('td',''),b=node('td',''),c=node('td',''),d=node('td','');a.append(node('strong',r.title),node('div',r.bvid,'mono'));let details=node('details','');details.append(node('summary','查看分类依据与记录'));details.append(node('p',r.reason));details.append(node('p',r.collections.join(' / ')));if(r.historically_reserved)details.append(node('p',r.historical_reservation_conflict?'旧保留记录冲突：已有后来使用证据。':'原保留材料：不自动放行。'));for(let e of r.exposure_reasons)details.append(node('div',e.kind+' · '+e.source,'mono'));if(!r.exposure_reasons.length)details.append(node('p','没有检索到曝光记录。不能证明未登记的人工阅读不存在。'));details.append(node('p','本地字幕文件数：'+r.subtitle_count));a.append(details);b.append(node('span',labels[r.partition],'tag '+r.partition));c.append(node('div',r.date||'日期未知'),node('small',r.date_basis==='title'?'标题日期':r.date_basis==='platform_header'?'平台头部日期':'待补元数据'),node('div',members[r.membership]));let gb=node('button',r.group_id);gb.onclick=()=>{el('search').value=r.group_id;limit=100;render()};d.append(gb,node('div',r.event_families.join(' / '),'mono'),node('div',exp[r.exposure]));tr.append(a,b,c,d);el('body').append(tr)}el('more').hidden=found.length<=limit}
for(let id of ['search','partition','member','exposure','dated'])el(id).addEventListener(id==='search'?'input':'change',()=>{limit=100;render()});el('more').onclick=()=>{limit+=100;render()};el('clear').onclick=()=>{for(let id of ['search','partition','member','exposure','dated'])el(id).value='';limit=100;render()};render();
</script></html>'''
if args.run != 'run_001':
    page=page.replace('版本 001','版本 '+args.run.removeprefix('run_'))
    page=page.replace('会员标记待确认：清单中实际使用<strong>《第中文数字期》</strong>，没有【】标题，暂记“会员候选”。','用户已确认：761个<strong>《第中文数字期》</strong>视频归为会员视频。')
(p/'REVIEW.html').write_text(page.replace('DATA_PLACEHOLDER',data),encoding='utf-8')
assert 'DATA_PLACEHOLDER' not in (p/'REVIEW.html').read_text(encoding='utf-8')
print(p/'REVIEW.html')
